import SwiftUI
import Observation

// MARK: - 数据模型
struct User: Codable, Identifiable, Sendable {
    let id: Int
    let name: String
    let email: String
}

// MARK: - 统一错误类型
enum NetworkError: Error, LocalizedError, Sendable {
    case badURL
    case invalidResponse
    case decodingFailed

    var errorDescription: String? {
        switch self {
        case .badURL:           return "URL 无效"
        case .invalidResponse:  return "服务器响应异常"
        case .decodingFailed:   return "数据解析失败"
        }
    }
}

// MARK: - 网络层（actor 保证状态安全，可被多处共享）
actor UserAPI {
    static let shared = UserAPI()
    private let session: URLSession

    private init() {
        let config = URLSessionConfiguration.ephemeral
        config.timeoutIntervalForRequest = 10
        self.session = URLSession(configuration: config)  // 复用同一个 session
    }

    func fetchUsers() async throws -> [User] {
        guard let url = URL(string: "https://jsonplaceholder.typicode.com/users") else {
            throw NetworkError.badURL
        }
        // data(from:) 在 Task 被取消时会抛出 CancellationError
        let (data, response) = try await session.data(from: url)
        guard let http = response as? HTTPURLResponse,
              (200...299).contains(http.statusCode) else {
            throw NetworkError.invalidResponse
        }
        do {
            return try JSONDecoder().decode([User].self, from: data)
        } catch {
            throw NetworkError.decodingFailed
        }
    }
}

// MARK: - ViewModel（@MainActor 保证 UI 状态只在主线程更新）
@MainActor
@Observable
final class UserListViewModel {
    enum State {
        case idle
        case loading
        case loaded([User])
        case failed(String)
    }

    private(set) var state: State = .idle
    private var fetchTask: Task<Void, Never>?

    func load() {
        fetchTask?.cancel()                     // ① 取消上一次未完成的请求，避免竞态
        fetchTask = Task {
            state = .loading
            do {
                let users = try await UserAPI.shared.fetchUsers()
                guard !Task.isCancelled else { return }   // ② 取消后不再写状态
                state = .loaded(users)
            } catch is CancellationError {
                // 用户主动取消，静默忽略，不打扰 UI
            } catch {
                state = .failed(error.localizedDescription)
            }
        }
    }

    func retry() {
        state = .idle
        load()
    }
}

// MARK: - View
struct UserListView: View {
    @State private var viewModel = UserListViewModel()

    var body: some View {
        NavigationStack {
            Group {
                switch viewModel.state {
                case .idle:
                    ContentUnavailableView(
                        "准备就绪",
                        systemImage: "person.crop.circle.badge.questionmark"
                    )
                case .loading:
                    ProgressView("加载中…")
                case .loaded(let users):
                    List(users) { user in
                        VStack(alignment: .leading, spacing: 4) {
                            Text(user.name)
                                .font(.headline)
                            Text(user.email)
                                .font(.subheadline)
                                .foregroundStyle(.secondary)
                        }
                    }
                    .refreshable { viewModel.load() }   // 下拉刷新
                case .failed(let message):
                    ContentUnavailableView(
                        "加载失败",
                        systemImage: "exclamationmark.triangle",
                        description: Text(message)
                    )
                    Button("重试") { viewModel.retry() }
                }
            }
            .navigationTitle("用户列表")
            .toolbar {
                Button("刷新") { viewModel.load() }
            }
        }
        .task { viewModel.load() }   // ③ 视图出现触发、消失自动取消
    }
}

